#include <vector>

int sum(const std::vector<int>& values)
{
    int total{ 0 };
    for (int value : values)
    {
        total += value;
    }
    return total;
}

unitTests:
TEST("a few numbers") { CHECK_EQ(sum({ 1, 2, 3, 4 }), 10); }
TEST("negatives") { CHECK_EQ(sum({ -5, 5, -3 }), -3); }
TEST("one element") { CHECK_EQ(sum({ 42 }), 42); }
TEST("empty") { CHECK_EQ(sum({}), 0); }

